<?php require __DIR__.'/inc/header.php';$title='Engagement';$pdo=db();$wish=$pdo->query('SELECT COUNT(*) FROM wishlists')->fetchColumn();$compare=$pdo->query('SELECT COUNT(*) FROM compares')->fetchColumn();$reviews=$pdo->query('SELECT COUNT(*) FROM reviews')->fetchColumn();$comments=$pdo->query("SELECT COUNT(*) FROM comments WHERE status='pending'")->fetchColumn();$popular=$pdo->query('SELECT p.name,COUNT(w.id) c FROM products p LEFT JOIN wishlists w ON w.product_id=p.id GROUP BY p.id ORDER BY c DESC LIMIT 10')->fetchAll();?><div class="grid grid-cols-2 lg:grid-cols-4 gap-3"><?php foreach([['Wishlist',$wish,'solar:heart-linear'],['Compare',$compare,'solar:transfer-horizontal-linear'],['Reviews',$reviews,'solar:star-linear'],['Pending Comments',$comments,'solar:chat-round-dots-linear']] as $x):?><div class="shine grad600 text-white rounded-2xl p-5 soft"><span class="iconify text-2xl" data-icon="<?=$x[2]?>"></span><div class="text-xs text-white/70 mt-3"><?=$x[0]?></div><div class="text-3xl font-black mt-1"><?=$x[1]?></div></div><?php endforeach;?></div><div class="bg-white border rounded-2xl p-5 mt-6 soft"><div class="font-black">Most Wishlisted Products</div><div class="mt-4 space-y-2"><?php foreach($popular as $r):?><div class="flex items-center justify-between p-3 rounded-xl bg-slate-50"><b><?=e($r['name'])?></b><span class="text-sm font-bold"><?=$r['c']?> saves</span></div><?php endforeach;?></div></div><?php require __DIR__.'/inc/footer.php'; ?>
